import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Редактор","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor/index.md","filePath":"guide/editor/index.md","lastUpdated":0}`),a={name:`guide/editor/index.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="редактор" tabindex="-1">Редактор <a class="header-anchor" href="#редактор" aria-label="Permalink to “Редактор”">​</a></h1><p>Всё, что работает внутри редактора Народной карты: загрузка данных, работа с геометрией и переключатели вкладки <strong>«Редактор»</strong> в попапе настроек.</p><p>Попап открывается кнопкой-шестерёнкой в шапке редактора, рядом с нативными кнопками. Настройки применяются сразу и запоминаются в браузере.</p><h2 id="upload" tabindex="-1">Загрузка и конвертация геоданных <a class="header-anchor" href="#upload" aria-label="Permalink to “Загрузка и конвертация геоданных”">​</a></h2><p><strong>Где:</strong> кнопка «Загрузить полигоны» на панели редактора.</p><p>Расширение принимает файл, конвертирует геометрию и атрибуты в формат Блокнота картографа и записывает результат в <code>index.json</code> за выбранную дату. Папка <code>Приложения/Блокнот картографа Народной карты</code> создаётся при первой загрузке, внутри — подпапки с датами в формате <code>гггг-мм-дд</code>.</p><p>Поддерживаются Shapefile (архив <code>.zip</code>), GeoJSON, GPX, KML, KMZ, TopoJSON и WKT. Полная таблица — в разделе <a href="/yamapper/guide/formats">«Форматы»</a>.</p><p>Как это работает:</p><ol><li>Перетащите файл в окно загрузки или нажмите «Выбрать файл».</li><li>Дождитесь конвертации — под каждым файлом появится статус.</li><li>Проверьте <a href="#notebook-date">дату блокнота</a> и нажмите «Загрузить».</li><li>Расширение проверит доступ к Диску, прочитает текущий <code>index.json</code> за эту дату, допишет новые объекты и сохранит файл обратно.</li></ol><p>Если запись за выбранную дату уже существует, она <strong>дополняется</strong>, а не затирается: старые объекты остаются на месте.</p><p>Основные сценарии:</p><ul><li><strong>GeoJSON из QGIS.</strong> Экспортируйте слой в GeoJSON (EPSG:4326), перетащите файл, выберите дату — полигоны появятся в блокноте с сохранением названий.</li><li><strong>Shapefile от заказчика.</strong> Соберите <code>.shp</code>, <code>.shx</code>, <code>.dbf</code> и <code>.prj</code> в один <code>.zip</code> и загрузите архив. Кодировка атрибутов определяется автоматически; если названия «кракозябрами» — переэкспортируйте слой в UTF-8.</li><li><strong>Трек из GPX.</strong> Загрузите <code>.gpx</code> — точки и линии попадут в блокнот как отдельные объекты.</li><li><strong>Несколько файлов сразу.</strong> Перетащите пачку: файлы обработаются по очереди, а результат уйдёт в блокнот одним сохранением.</li></ul><div class="tip custom-block"><p class="custom-block-title">Ограничение по вершинам</p><p>У объектов блокнота есть лимит вершин. Держите его под контролем с помощью <a href="#point-counter">счётчика вершин</a> — он показывает остаток до лимита.</p></div><h2 id="notebook-date" tabindex="-1">Дата блокнота <a class="header-anchor" href="#notebook-date" aria-label="Permalink to “Дата блокнота”">​</a></h2><p><strong>Где:</strong> поле «Дата блокнота» в окне загрузки.</p><p>Дата определяет, в какую запись блокнота попадут данные. По умолчанию стоит сегодняшняя дата; формат отображения — <code>дд-мм-гггг</code>, в файловой системе — <code>гггг-мм-дд</code>.</p><p>В календаре даты, на которые в блокноте уже есть запись, помечены отдельно (в легенде — «В блокноте уже есть запись на эту дату»). Это не ошибка: загрузка в такую дату дополнит существующую запись.</p><p>Сценарии:</p><ul><li><strong>Правка за сегодня.</strong> Оставьте дату по умолчанию — данные добавятся к текущей записи.</li><li><strong>Работа над задачей за прошлую дату.</strong> Выберите дату из задания, чтобы объекты легли в ту же запись, что и остальная работа.</li><li><strong>Проверка без порчи данных.</strong> Сначала загрузите в отдельную дату, убедитесь, что геометрия верна, и только потом переносите в рабочую.</li></ul><h2 id="tracing" tabindex="-1">Трассировка загруженного полигона <a class="header-anchor" href="#tracing" aria-label="Permalink to “Трассировка загруженного полигона”">​</a></h2><p><strong>Где:</strong> нативная кнопка «Трассировка» в редакторе.</p><p>Загруженный полигон ведёт себя как обычный объект блокнота: его можно выбрать и передать в штатную трассировку редактора. Расширение не подменяет инструмент, а готовит объект так, чтобы нативная трассировка его приняла.</p><p>Сценарий: загрузили контур квартала из Shapefile, выбрали его в блокноте, нажали «Трассировка» и обвели смежный объект по готовой границе — без ручной подгонки вершин.</p><h2 id="cut" tabindex="-1">Разрез растительности и водоёмов <a class="header-anchor" href="#cut" aria-label="Permalink to “Разрез растительности и водоёмов”">​</a></h2><p><strong>Где:</strong> кнопка разреза в нативном тулбаре редактора, когда открыт объект растительности или водоёма.</p><p>В редакторе есть нож для строений, но для растительности такого инструмента нет. Расширение добавляет кнопку «Разрезать растительность» и «Разрезать водоём»: линия делится в точке клика, а обе части остаются частями того же объекта.</p><ul><li>Клик по линии — разрез в этом месте.</li><li>Для замкнутой линии первый клик ставит границу, второй делит кольцо на две части; между кликами показывается подсказка.</li><li>Слишком короткая часть не создаётся — появится сообщение «Слишком короткая часть — разрез не сделан».</li><li>Разрез попадает в историю редактора одной командой: <code>Ctrl+Z</code> отменяет его целиком.</li></ul><p>Инструмент работает только на линиях растительности и водоёмов; на других объектах кнопка не появляется.</p><h2 id="split-view" tabindex="-1">Раздельный вид <a class="header-anchor" href="#split-view" aria-label="Permalink to “Раздельный вид”">​</a></h2><p><strong>Где:</strong> Настройки → Редактор → «Раздельный вид».</p><p>Окно редактора делится на две части: слева — Народная карта, справа — <a href="https://nakarte.me/" target="_blank" rel="noreferrer">nakarte.me</a> с историческими картами и спутниковыми снимками. Панорамирование и масштаб синхронизируются: двигаете карту слева — едет и правая часть.</p><p>Что важно знать:</p><ul><li>Выбранные в Nakarte слои и настройки запоминаются между открытиями.</li><li>В раздельном виде контролы Nakarte скрываются, чтобы не мешать карте.</li><li>Позиция курсора показывается на обеих половинах — удобно сверять контуры.</li><li>Кнопка раздельного вида в тулбаре подсвечивается, когда режим включён.</li></ul><p>Сценарии:</p><ul><li><strong>Сверка с исторической картой.</strong> Включите вид, выберите в Nakarte слой генштаба и обводите объект по старой границе.</li><li><strong>Спутник как подложка.</strong> Сравните свежий снимок с текущей геометрией, не переключая вкладки.</li><li><strong>Работа на двух мониторах.</strong> Оставьте раздельный вид включённым: режим сохраняется и восстанавливается при следующем открытии.</li></ul><h2 id="notes" tabindex="-1">Заметки <a class="header-anchor" href="#notes" aria-label="Permalink to “Заметки”">​</a></h2><p><strong>Где:</strong> Настройки → Редактор → «Заметки». После включения появляются кнопка «Заметки» в нижней панели и плитка «Заметки» в выборе категории.</p><p>Заметки — собственный слой пользователя: точки, линии, многоугольники, квадраты и круги, которые не являются объектами Народной карты. Они хранятся на вашем Яндекс Диске в <code>Приложения/Nmap Uploader/notes</code> и не смешиваются с Блокнотом.</p><p>Что можно делать в панели заметок:</p><ul><li>создавать заметку выбранной формы и рисовать её на карте;</li><li>задавать название, расширенное описание, цвет, прозрачность, толщину, заливку и узор, подпись на карте;</li><li>выбирать иконку и группу, скрывать и показывать объекты;</li><li>фильтровать список по виду, группе и видимости, сортировать по названию и дате;</li><li>отмечать несколько заметок и удалять их пачкой, переносить в группу;</li><li>находить заметку на карте кнопкой «Найти на карте»;</li><li>сворачивать и разворачивать панель, раскрывать на весь экран.</li></ul><p>Сценарии:</p><ul><li><strong>Список мест для проверки.</strong> Поставьте точки с описанием «проверить адрес», сгруппируйте по району и скрывайте группу, когда работа закончена.</li><li><strong>Черновик контура.</strong> Нарисуйте многоугольник, подберите оформление, а после согласования перенесите геометрию в Блокнот.</li><li><strong>Личная карта.</strong> Держите слой заметок включённым как рабочую пометку поверх данных блокнота.</li></ul><div class="warning custom-block"><p class="custom-block-title">Функция в статусе beta</p><p>Панель заметок активно дорабатывается. Если что-то ведёт себя странно, приложите шаги воспроизведения в <a href="https://github.com/vibecodinguser/yamapper/issues" target="_blank" rel="noreferrer">Issues</a>.</p></div><h2 id="nspd" tabindex="-1">Загрузка из НСПД <a class="header-anchor" href="#nspd" aria-label="Permalink to “Загрузка из НСПД”">​</a></h2><p><strong>Где:</strong> Настройки → Редактор → «Загрузка из НСПД». Кнопка «Загрузка из НСПД» появляется на панели редактора.</p><p>Функция открывает Национальную систему пространственных данных на текущем участке карты и позволяет выгрузить найденные объекты — границы, кварталы, участки — в Блокнот картографа.</p><p>Как это работает:</p><ol><li>Включите тумблер. Если доступа к <code>nspd.gov.ru</code> ещё нет, в строке настройки появится кнопка «Разрешить доступ».</li><li>Нажмите кнопку на панели редактора — НСПД откроется в новом окне с текущими координатами.</li><li>На странице НСПД выберите объект и нажмите кнопку выгрузки в плавающем виджете.</li><li>Для записи в Блокнот расширение отдельно попросит доступ к Яндекс Диску.</li></ol><p>Сценарии:</p><ul><li><strong>Границы АТД.</strong> Найдите район или поселение и выгрузите границу как основу для дальнейшей работы.</li><li><strong>Кадастровый квартал.</strong> Откройте участок по кадастровому номеру и перенесите его контур в блокнот.</li></ul><div class="info custom-block"><p class="custom-block-title">Разрешения необязательные</p><p>Пока функция выключена, расширение не обращается к НСПД. Выключение тумблера не отзывает уже выданное разрешение — это можно сделать в настройках браузера.</p></div><h2 id="geo-services" tabindex="-1">Внешние геосервисы <a class="header-anchor" href="#geo-services" aria-label="Permalink to “Внешние геосервисы”">​</a></h2><p><strong>Где:</strong> Настройки → Редактор → «Внешние геосервисы».</p><p>Меню «Перейти» в редакторе открывает текущий участок карты во внешнем сервисе: 2GIS, Google Maps, OpenStreetMap, Nakarte, Wikimapia, Retromap, Google Earth, Bing Maps, Mapillary, Copernicus, Here Maps, ЭтоМесто, Strava Heatmap и Портал НСПД.</p><p>В настройках можно:</p><ul><li>включать и выключать отдельные сервисы;</li><li>менять порядок пунктов меню — перетаскиванием или стрелками ↑ и ↓;</li><li>видеть, сколько сервисов активно: «N из M активны».</li></ul><p>Порядок и набор сервисов сохраняются между сессиями.</p><p>Сценарии:</p><ul><li><strong>Проверка адреса.</strong> Откройте точку в 2GIS, чтобы увидеть организацию и подъезды.</li><li><strong>Старая карта.</strong> Перейдите в ЭтоМесто или Retromap и сравните границу с историческим планом.</li><li><strong>Свежий снимок.</strong> Откройте Google Earth или Copernicus для проверки изменений местности.</li></ul><h2 id="point-counter" tabindex="-1">Счётчик вершин <a class="header-anchor" href="#point-counter" aria-label="Permalink to “Счётчик вершин”">​</a></h2><p><strong>Где:</strong> Настройки → Редактор → «Счётчик вершин».</p><p>Показывает, сколько вершин осталось до лимита в 500. Счётчик появляется при редактировании объекта и обновляется на лету.</p><p>Особенности:</p><ul><li>у многочастного полигона считается только активная часть;</li><li>у объекта из нескольких линий счётчик не показывается;</li><li>при достижении лимита появляется предупреждение, при превышении — на сколько.</li></ul><p>Сценарии:</p><ul><li><strong>Упрощение контура.</strong> Видно, что до лимита осталось 12 вершин — самое время убрать лишние точки, а не ловить ошибку сохранения.</li><li><strong>Многочастный объект.</strong> Переключайтесь между частями: счётчик считает ту, которую вы правите сейчас.</li></ul><h2 id="reload-after-upload" tabindex="-1">Автообновление после загрузки <a class="header-anchor" href="#reload-after-upload" aria-label="Permalink to “Автообновление после загрузки”">​</a></h2><p><strong>Где:</strong> Настройки → Редактор → «Автообновление после загрузки».</p><p>После успешной загрузки страница карты перезагружается сама, и новые объекты сразу появляются в блокноте. Настройка запоминается отдельно для пользователя.</p><p>Когда помогает:</p><ul><li>блокнот не подхватывает изменения без перезагрузки;</li><li>вы загружаете данные пачками и не хотите каждый раз обновлять вручную.</li></ul><p>Когда лучше выключить: если в редакторе есть несохранённые правки — сначала сохраните их, иначе перезагрузка их потеряет.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to “Что дальше”">​</a></h2><ul><li><a href="/yamapper/guide/moderation/">Модерация</a> — фильтр истории правок и наблюдение за объектами.</li><li><a href="/yamapper/guide/style/">Стиль</a> — цвет обводки, тема и язык.</li><li><a href="/yamapper/guide/faq">Вопросы и типичные ошибки</a>.</li></ul>`,74)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};